// This script is meant to be run after `npm run build` to generate the PDF version of the CV.
import http from 'http';
import { readFile } from 'fs/promises';
import express from 'express';
import { promisify } from 'util';
import { chromium } from 'playwright';

import { buildDir, pdfOutPath } from './pdf-details.js';
import { LIVE_URL } from './site-config.js';

// Cap for the standard CV export. Verbose CVs are not generated by this script and
// are intentionally exempt from this limit.
const STANDARD_CV_MAX_PAGES = 2;

// Chromium writes the PDF page tree as plain, uncompressed dictionaries, so the
// page count can be read without a PDF parser. Require the page objects and the
// tree's declared /Count to agree rather than trusting a single signal.
function countPdfPages(bytes) {
  const raw = bytes.toString('latin1');
  const pageObjects = raw.match(/\/Type\s*\/Page\b/g)?.length ?? 0;
  const declaredCounts = [...raw.matchAll(/\/Count\s+(\d+)\b/g)].map(match => Number(match[1]));
  const declaredCount = declaredCounts.length > 0 ? Math.max(...declaredCounts) : 0;

  if (pageObjects === 0 || declaredCount === 0) {
    throw new Error('Could not determine the PDF page count: no page tree found in the export.');
  }
  if (pageObjects !== declaredCount) {
    throw new Error(
      `Could not determine the PDF page count: ${pageObjects} page object(s) but the page tree declares ${declaredCount}.`,
    );
  }
  return pageObjects;
}

// The PDF is rendered from a temporary localhost server, so root-relative anchors
// (e.g. `/cv/verbose`) would be baked into the PDF as localhost links. Rewrite them
// against the public site URL before exporting.
const siteOrigin = new URL(LIVE_URL).origin;

const server = http.createServer(express().use(express.static(buildDir)));
const listen = promisify(server.listen.bind(server));
await listen(0);

const { port } = server.address();
console.log(`Server listening on http://localhost:${port}`);

const browser = await chromium.launch();

try {
  const page = await browser.newPage();
  console.log(`Generating PDF from http://localhost:${port}/cv`);
  await page.emulateMedia({ colorScheme: 'light' });
  await page.goto(`http://localhost:${port}/cv`, { waitUntil: 'networkidle', timeout: 60000 });
  const rewrittenLinks = await page.evaluate(origin => {
    let count = 0;
    for (const anchor of document.querySelectorAll('a[href]')) {
      const href = anchor.getAttribute('href').trim();
      if (!href.startsWith('/') || href.startsWith('//')) continue;
      anchor.setAttribute('href', `${origin}${href}`);
      count++;
    }
    return count;
  }, siteOrigin);
  console.log(`Rewrote ${rewrittenLinks} root-relative link(s) to ${siteOrigin}`);
  console.log(`Exporting PDF`);
  await page.pdf({ path: pdfOutPath });
  console.log(`PDF exported to ${pdfOutPath}`);

  const pageCount = countPdfPages(await readFile(pdfOutPath));
  if (pageCount > STANDARD_CV_MAX_PAGES) {
    throw new Error(
      `CV PDF is ${pageCount} pages long, but the standard CV must stay within ${STANDARD_CV_MAX_PAGES} pages. ` +
        `Trim content or tighten the layout. The over-limit PDF is at ${pdfOutPath}.`,
    );
  }
  console.log(`PDF has ${pageCount} page(s), within the ${STANDARD_CV_MAX_PAGES}-page limit`);
} finally {
  await browser.close();
  server.close();
}
